    --},
    --master = {
    --    -- See https://wiki.hypr.land.org/Configuring/Master-Layout/ for more
    --    new_is_master = true,
    --},
    --gestures = {
    --    -- See https://wiki.hypr.land.org/Configuring/Variables/ for more
    --    workspace_swipe = false,
    --},
    misc = {
        -- See https://wiki.hypr.land.org/Configuring/Variables/ for more
        force_default_wallpaper = -1, -- Set to 0 or 1 to disable the anime mascot wallpapers
    },
    -- Example per-device config
    -- See https://wiki.hypr.land.org/Configuring/Keywords/#per-device-input-configs for more
    -- Example windowrule v1
    -- windowrule = float, ^(kitty)$
    -- Example windowrule v2
    -- windowrulev2 = float,class:^(kitty)$,title:^(kitty)$
    -- See https://wiki.hypr.land.org/Configuring/Window-Rules/ for more
    -- See https://wiki.hypr.land.org/Configuring/Keywords/ for more
    -- Example binds, see https://wiki.hypr.land.org/Configuring/Binds/ for more
    -- Move focus with mainMod + arrow keys
    -- Switch workspaces with mainMod + [0-9]
